export const KeyIcon = icon(Key01Icon, "KeyIcon")
export const VariablesIcon = icon(VariableIcon, "VariablesIcon")
export const WebhooksIcon = icon(WebhookIcon, "WebhooksIcon")
export const IntegrationsIcon = icon(BlockGameIcon, "IntegrationsIcon")
export const DeveloperDocsIcon = icon(CodeIcon, "DeveloperDocsIcon")
export const BuildingIcon = icon(Building02Icon, "BuildingIcon")
export const RolesIcon = icon(ShieldKeyIcon, "RolesIcon")
export const MobileIcon = icon(SmartPhone01Icon, "MobileIcon")
/* The model catalog (DES-169), under Configuration. */
export const ModelsIcon = icon(CpuIcon, "ModelsIcon")
export const TelephonyIcon = icon(TelephoneIcon, "TelephonyIcon")
export const SettingsIcon = icon(Settings01Icon, "SettingsIcon")
export const MessagingSettingsIcon = icon(
  BubbleChatIcon,
  "MessagingSettingsIcon",
)
export const ChevronDownIcon = icon(ArrowDown01Icon, "ChevronDownIcon")
/** The hover "+" on Personas and Scenarios — creates one without leaving the nav. */
export const NewItemIcon = icon(PlusSignIcon, "NewItemIcon")

"use client"

import Image from "next/image"
import * as React from "react"

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Button } from "@/components/ui/button"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { Separator } from "@/components/ui/separator"
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuAction,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarTrigger,
  useSidebar,
} from "@/components/ui/sidebar"
import { cn } from "@/lib/utils"
import {
  BatchCallsIcon,
  BuildingIcon,
  ChevronDownIcon,
  ConversationsIcon,
  DashboardIcon,
  DeveloperDocsIcon,
  GlobalPromptsIcon,
  IntegrationsIcon,
  KeyIcon,
  KnowledgeIcon,
  MessagingIcon,
  MessagingSettingsIcon,
  MobileIcon,
  ModelsIcon,
  NewItemIcon,
  PersonasIcon,
  PlaygroundIcon,
  QualityIcon,
  ReportsIcon,
  RolesIcon,
  ScenariosIcon,
  SettingsIcon,
  TasksIcon,
  TelephonyIcon,
  TemplateIcon,
  VariablesIcon,
  VoiceLibraryIcon,
  WebhooksIcon,
} from "@/components/app-shell-icons"

/**
 * The app around any mockup screen, shared by every mockup that wants the
 * product chrome: an inset sidebar over a tinted page, and a header carrying
 * the breadcrumb and the account. Pass `active` to highlight the nav item the
 * screen lives under.
 *
 * Playground sits above the groups rather than inside one — it is the entry
 * point, not a build step. Configuration starts closed because it is the group
 * you visit once and then leave alone.
 */

interface NavItem {
  /** Label for the hover "+", on the two things you create most. */
  action?: string
  icon: React.ComponentType
  title: string
}

const PLAYGROUND: NavItem = { icon: PlaygroundIcon, title: "Playground" }

const NAV: { defaultOpen: boolean; items: NavItem[]; label: string }[] = [
  {
    defaultOpen: true,
    label: "Agents",
    items: [
      { action: "New persona", icon: PersonasIcon, title: "Personas" },
      { action: "New scenario", icon: ScenariosIcon, title: "Scenarios" },
      { icon: KnowledgeIcon, title: "Knowledge Bases" },
      { icon: BatchCallsIcon, title: "Batch Calls" },
      { icon: TemplateIcon, title: "Scenario Templates" },
      { icon: GlobalPromptsIcon, title: "Global Prompts" },
      { icon: VoiceLibraryIcon, title: "Voice Library" },
    ],
  },
  {
    defaultOpen: true,
    label: "Monitor",
    items: [
      { icon: DashboardIcon, title: "Dashboard" },
      { icon: ConversationsIcon, title: "Conversations" },
      { icon: MessagingIcon, title: "Messaging" },
      { icon: QualityIcon, title: "Quality Dashboard" },
      { icon: ReportsIcon, title: "Reports" },
      { icon: TasksIcon, title: "Tasks" },
    ],
  },
  {
    defaultOpen: false,
    label: "Configuration",
    items: [
      { icon: KeyIcon, title: "API Keys" },
      { icon: VariablesIcon, title: "Variables" },
      { icon: WebhooksIcon, title: "Webhooks" },
      { icon: IntegrationsIcon, title: "Integrations" },
      { icon: DeveloperDocsIcon, title: "Developer Docs" },
      { icon: BuildingIcon, title: "Organizations" },
      /* DES-170. Roles are platform-wide and Sarj-only in Phase 1, so they sit
         beside Organizations rather than inside one. */
      { icon: RolesIcon, title: "Roles" },
      { icon: MobileIcon, title: "Phone Numbers" },
      /* DES-169. The catalog needs a home in the nav, and Configuration is
         where the other platform-wide, Sarj-staff-only surfaces already sit. */
      { icon: ModelsIcon, title: "Models" },
      { icon: TelephonyIcon, title: "Telephony" },
      { icon: SettingsIcon, title: "Global Settings" },
      { icon: MessagingSettingsIcon, title: "Messaging Settings" },
    ],
  },
]

function NavLink({
  active,
  item,
  onNavigate,
}: {
  active: boolean
  item: NavItem
  onNavigate?: (title: string) => void
}) {
  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        isActive={active}
        tooltip={item.title}
        onClick={() => onNavigate?.(item.title)}
      >
        <item.icon />
        <span className="truncate">{item.title}</span>
      </SidebarMenuButton>
      {/* `rounded-sm` in place of the primitive's `rounded-md` and `right-2` in
          place of `right-1`, both as the app has them.

          The glyph size is deliberately NOT the app's `[&>svg]:size-full`. That
          class works there because its plus is a hand-drawn 20×20 icon whose
          path spans only 6.5→13.5, so filling the box still draws a 7px plus.
          Ours is HugeIcons' PlusSignIcon, whose ink fills 16 of its 24 viewBox
          units — the same class drew a 12px plus, nearly twice the app's.
          `size-2.5` renders it at 10px, putting the drawn plus at 6.7px. */}
      {item.action ? (
        <SidebarMenuAction
          aria-label={item.action}
          className="top-1.5 right-2 rounded-sm border border-input bg-background text-muted-foreground hover:bg-accent hover:text-foreground [&>svg]:size-2.5"
        >
          <NewItemIcon />
        </SidebarMenuAction>
      ) : null}
    </SidebarMenuItem>
  )
}

/**
 * Collapsed to the icon rail there is no room for a section label, so the
 * groups are forced open and the label — the only thing that could close them —
 * is disabled.
 */
function NavGroup({
  active,
  defaultOpen,
  items,
  label,
  onNavigate,
}: {
  active: string
  defaultOpen: boolean
  items: NavItem[]
  label: string
  onNavigate?: (title: string) => void
}) {
  const { state } = useSidebar()
  const isCollapsed = state === "collapsed"
  const [open, setOpen] = React.useState(defaultOpen)

  return (
    <Collapsible
      disabled={isCollapsed}
      onOpenChange={isCollapsed ? undefined : setOpen}
      open={isCollapsed || open}
    >
      <SidebarGroup>
        <SidebarGroupLabel asChild>
          <CollapsibleTrigger className="flex w-full cursor-pointer items-center justify-between hover:bg-accent/50">
            <span>{label}</span>
            <ChevronDownIcon
              className={cn(
                "transition-transform duration-200 ease-out-cubic motion-reduce:transition-none",
                open ? "rotate-0" : "-rotate-90",
              )}
            />
          </CollapsibleTrigger>
        </SidebarGroupLabel>
        <CollapsibleContent>
          <SidebarGroupContent>
            <SidebarMenu>
              {items.map((item) => (
                <NavLink
                  active={item.title === active}
                  item={item}
                  key={item.title}
                  onNavigate={onNavigate}
                />
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </CollapsibleContent>
      </SidebarGroup>
    </Collapsible>
  )
}

/** Breadcrumb start, account end — the row every page in the app sits under. */
function AppHeader({
  breadcrumb,
  showSettings,
}: {
  breadcrumb: string
  showSettings: boolean
}) {
  return (
    <header className="flex h-16 shrink-0 items-center justify-between gap-4 px-4">
      <Breadcrumb>
        <BreadcrumbList>
          <BreadcrumbItem>
            <BreadcrumbLink href="#">Home</BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbSeparator />
          <BreadcrumbItem>
            <BreadcrumbPage>{breadcrumb}</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex shrink-0 items-center gap-2">
        <Button size="sm" variant="outline">
          <DeveloperDocsIcon />
          Developer Doc
        </Button>
        {/* The same allowlist the nav reads. The app has this gear on its own
            check today, which is how an admin gets a second dead end to the
            page the sidebar already sent them to. */}
        {showSettings ? (
          <Button aria-label="Global settings" size="icon-sm" variant="outline">
            <SettingsIcon />
          </Button>
        ) : null}
        {/* Wrapped, rather than given `self-center`: the primitive ships
            `data-vertical:self-stretch`, and an attribute variant outranks a
            plain utility, so the rule stretched to the 28px row, got held to
            h-4, and settled at the top of it — 6px above the centre the buttons
            and the avatar share. Inside a wrapper of its own the flex line is
            the rule's own height, so stretching changes nothing and the wrapper
            is what the header centres. */}
        <div className="flex items-center">
          <Separator className="mx-1 h-4" orientation="vertical" />
        </div>
        {/* A rounded square at the same radius and height as the two buttons,
            not a circle. The app's account button is Clerk's, and Clerk does not
            inherit the app's CSS vars — so the real header sets its avatar
            radius to a 0.625rem literal, which is `--radius`, which is
            `rounded-lg`. A circle here is the one thing in this row that would
            not be in the app. `after:` and the fallback carry the primitive's
            own `rounded-full`, so both have to be squared off with it. */}
        <Avatar className="size-7 rounded-lg after:rounded-lg">
          <AvatarFallback className="rounded-lg">TA</AvatarFallback>
        </Avatar>
      </div>
    </header>
  )
}

export function AppShell({
  active,
  breadcrumb,
  hiddenItems,
  onNavigate,
  children,
}: {
  /** Title of the sidebar item this screen lives under, e.g. "Personas". */
  active: string
  /** Page label in the breadcrumb; defaults to `active`. */
  breadcrumb?: string
  /**
   * Nav item titles this viewer's role cannot open, so the menu holds only
   * what they can reach. Omit it and the nav is the full one, which is what
   * every other mockup wants.
   */
  hiddenItems?: readonly string[]
  /** Called with a nav item's title when it is clicked, so a mockup can make
   * the destinations it covers actually switch. Items it ignores stay inert. */
  onNavigate?: (title: string) => void
  children: React.ReactNode
}) {
  const hidden = new Set(hiddenItems ?? [])
  const groups = NAV.map((group) => ({
    ...group,
    items: group.items.filter((item) => !hidden.has(item.title)),
  })).filter((group) => group.items.length > 0)

  return (
    <SidebarProvider className="min-h-0 flex-1">
      {/* The sidebar pins to the viewport as it does in the app, so it clears
          the mockup shell's own header rather than sliding under it. */}
      <Sidebar className="pt-12" collapsible="icon" variant="inset">
        <SidebarHeader className="px-2 pt-2 pb-1">
          <div className="flex items-center justify-between group-data-[state=collapsed]:justify-center">
            {/* 56×32 is the size the app's own header renders it at. */}
            <Image
              alt="sarj.ai"
              className="group-data-[state=collapsed]:hidden"
              height={32}
              priority
              src="/logo.png"
              width={56}
            />
            <SidebarTrigger className="text-muted-foreground" />
          </div>
        </SidebarHeader>

        <SidebarContent>
          <SidebarGroup className="pt-2 pb-0">
            <SidebarGroupContent>
              <SidebarMenu>
                <NavLink
                  active={PLAYGROUND.title === active}
                  item={PLAYGROUND}
                  onNavigate={onNavigate}
                />
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>

          {groups.map((group, index) => (
            <React.Fragment key={group.label}>
              {/* The rail hides section labels, so a rule stands in for the
                  grouping those labels carry when the nav is open. */}
              {index > 0 ? (
                <div className="mx-2 my-1 hidden h-px shrink-0 bg-sidebar-border group-data-[collapsible=icon]:block" />
              ) : null}
              <NavGroup
                active={active}
                /* A closed group hiding the item the screen is on reads as the
                   nav having lost its place, so the active item's group opens
                   regardless of where the group would otherwise start. */
                defaultOpen={
                  group.defaultOpen ||
                  group.items.some((item) => item.title === active)
                }
                items={group.items}
                label={group.label}
                onNavigate={onNavigate}
              />
            </React.Fragment>
          ))}
        </SidebarContent>
      </Sidebar>

      <SidebarInset className="min-w-0 overflow-hidden">
        <AppHeader
          breadcrumb={breadcrumb ?? active}
          showSettings={!hidden.has("Global Settings")}
        />
        {/* No gutter here: the page owns its p-3 lg:p-4, matching the header. */}
        <div className="flex min-h-0 flex-1 flex-col overflow-auto">
          {children}
        </div>
      </SidebarInset>
    </SidebarProvider>
  )
}

"use client"

import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  setToolbar,
  useToolbarEnabled,
  useToolbarSuppressed,
} from "@/components/staff-toolbar"
import { CommentIcon } from "@/components/workspace-icons"

/**
 * Turns Vercel Comments on for the mockup under it.
 *
 * The toolbar is opt-in — mounting it for everyone prompts *every* visitor to
 * log in to Vercel — but the opt-in used to be a query param you had to know
 * about, so a link sent without it was a dead end. This is that same switch
 * with an address: last in the shell header, identical on every mockup.
 *
 * It stays visible once the toolbar is up. The header is reviewer chrome
 * rather than part of the design being reviewed, and leaving it there is what
 * makes turning commenting back off something other than a typed URL.
 */
export function CommentToggle() {
  const enabled = useToolbarEnabled()
  const suppressed = useToolbarSuppressed()

  if (suppressed) return null

  /* The divider belongs to the toggle rather than to the header, so that
     hiding one for a screenshot cannot leave the other stranded. */
  return (
    <>
      <Separator
        orientation="vertical"
        className="h-5 data-vertical:self-center"
      />

      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            aria-label={
              enabled ? "Turn commenting off" : "Comment on this mockup"
            }
            aria-pressed={enabled}
            className={enabled ? undefined : "text-muted-foreground"}
            onClick={() => setToolbar(!enabled)}
            size="icon-sm"
            variant="ghost"
          >
            <CommentIcon />
          </Button>
        </TooltipTrigger>
        <TooltipContent>
          {enabled ? "Turn commenting off" : "Comment on this mockup"}
        </TooltipContent>
      </Tooltip>
    </>
  )
}

import { Alert02Icon, InformationCircleIcon } from "@hugeicons/core-free-icons"

import { icon } from "@/components/icon"

/** A maximum outside the recommended band. */
export const OutOfBandIcon = icon(Alert02Icon, "OutOfBandIcon")

/** Scope and timing of what a save here actually changes. */
export const ScopeNoteIcon = icon(InformationCircleIcon, "ScopeNoteIcon")

/**
 * What a field does, parked in the field rather than printed under it.
 *
 * The circled "i", not a "?". Two reasons: the platform's own hover-help is
 * `components/scenario/tools/form-components/tooltip-help.tsx` and it uses
 * Info, and this screen was already using Info for the scope note — so it was
 * carrying two different help glyphs at once.
 */
export const FieldHelpIcon = icon(InformationCircleIcon, "FieldHelpIcon")

"use client"

import * as React from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"

import { Alert, AlertDescription } from "@/components/ui/alert"
import { Field, FieldLabel } from "@/components/ui/field"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  MAX_WAIT_CEILING_SECONDS,
  RECOMMENDED_MAX_WAIT_CEILING_SECONDS,
  RECOMMENDED_MAX_WAIT_FLOOR_SECONDS,
  formatSeconds,
} from "@/lib/eou-timing-data"

import { FieldHelpIcon, OutOfBandIcon } from "./icons"

export type WaitWindowValue = {
  maxWaitSeconds: number
  minWaitSeconds: number
}

/**
 * Minimum and maximum wait — PRD requirements 4, 5 and 6.
 *
 * Each control says in plain language what it does and what raising or lowering
 * it means for the caller. Both are bounded, and a maximum outside the
 * recommended band warns.
 */
export function WaitWindow({
  disabled = false,
  idPrefix,
  onChange,
  value,
}: {
  disabled?: boolean
  idPrefix: string
  onChange: (value: WaitWindowValue) => void
  value: WaitWindowValue
}) {
  const { maxWaitSeconds, minWaitSeconds } = value
  const belowFloor = maxWaitSeconds < RECOMMENDED_MAX_WAIT_FLOOR_SECONDS
  const aboveCeiling = maxWaitSeconds > RECOMMENDED_MAX_WAIT_CEILING_SECONDS

  const handleNumber =
    (field: keyof WaitWindowValue) =>
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const next = Number(event.target.value)
      if (Number.isNaN(next)) return
      onChange({
        ...value,
        [field]: Math.min(Math.max(next, 0), MAX_WAIT_CEILING_SECONDS),
      })
    }

  return (
    <div className="flex flex-col gap-4">
      <div className="grid gap-4 md:grid-cols-2">
        <WaitField
          disabled={disabled}
          help="How long the agent waits after the caller seems finished. Lower feels snappier."
          id={`${idPrefix}-min-wait`}
          label="Minimum wait (seconds)"
          name="minimum wait"
          onChange={handleNumber("minWaitSeconds")}
          value={minWaitSeconds}
        />

        <WaitField
          disabled={disabled}
          help="The longest the agent waits when it isn't sure. Lower risks interrupting mid-sentence."
          id={`${idPrefix}-max-wait`}
          label="Maximum wait (seconds)"
          name="maximum wait"
          onChange={handleNumber("maxWaitSeconds")}
          value={maxWaitSeconds}
        />
      </div>

      <BandWarning
        aboveCeiling={aboveCeiling && !disabled}
        belowFloor={belowFloor && !disabled}
      />
    </div>
  )
}

/**
 * One wait field: the number, with its explanation parked on a hover target
 * inside the input rather than printed under it.
 *
 * The copy is the same either way — PRD requirement 4 asks each control to say
 * what it does — but a tooltip only says it to someone who goes looking. Worth
 * knowing that this trades always-visible guidance for a tighter form.
 */
function WaitField({
  disabled,
  help,
  id,
  label,
  name,
  onChange,
  value,
}: {
  disabled: boolean
  help: string
  id: string
  label: string
  /** The field said as prose, for the help button's screen-reader name — the
   * visible label carries "(seconds)", which reads as noise when spoken. */
  name: string
  onChange: (event: React.ChangeEvent<HTMLInputElement>) => void
  value: number
}) {
  return (
    <Field>
      <FieldLabel htmlFor={id}>{label}</FieldLabel>
      <InputGroup>
        <InputGroupInput
          disabled={disabled}
          id={id}
          max={MAX_WAIT_CEILING_SECONDS}
          min={0}
          onChange={onChange}
          step={0.1}
          type="number"
          value={value}
        />
        <InputGroupAddon align="inline-end">
          <Tooltip>
            <TooltipTrigger asChild>
              <InputGroupButton
                aria-label={`What ${name} does`}
                size="icon-xs"
                type="button"
              >
                <FieldHelpIcon />
              </InputGroupButton>
            </TooltipTrigger>
            <TooltipContent className="max-w-64">{help}</TooltipContent>
          </Tooltip>
        </InputGroupAddon>
      </InputGroup>
    </Field>
  )
}

/** Shipped copy, kept word for word so the mockup does not fork the warning. */
function BandWarning({
  aboveCeiling,
  belowFloor,
}: {
  aboveCeiling: boolean
  belowFloor: boolean
}) {
  const reduce = useReducedMotion()
  const message = belowFloor
    ? `A maximum wait below ${formatSeconds(RECOMMENDED_MAX_WAIT_FLOOR_SECONDS)} increases the chance of interrupting callers mid-sentence.`
    : aboveCeiling
      ? `A maximum wait above ${formatSeconds(RECOMMENDED_MAX_WAIT_CEILING_SECONDS)} leaves callers waiting whenever the model is unsure, which is the delay this setting exists to reduce.`
      : null

  return (
    <AnimatePresence initial={false} mode="wait">
      {message ? (
        <motion.div
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -4 }}
          initial={{ opacity: 0, y: -4 }}
          key={belowFloor ? "below" : "above"}
          transition={
            reduce
              ? { duration: 0 }
              : { duration: 0.2, ease: [0.215, 0.61, 0.355, 1] }
          }
        >
          <Alert>
            <OutOfBandIcon className="text-warning" />
            <AlertDescription>{message}</AlertDescription>
          </Alert>
        </motion.div>
      ) : null}
    </AnimatePresence>
  )
}

"use client"

import { useSyncExternalStore } from "react"

import { VercelToolbar } from "@vercel/toolbar/next"

/** Survives a reload, so a reviewer opts in once rather than per link. */
const STORAGE_KEY = "sarj-mockups:toolbar"

/* Two components read this store — the toolbar itself and the toggle in the
   shell header — and a write from one has to reach the other. `storage` only
   fires in the *other* tabs, so same-tab writes are fanned out here. */
const listeners = new Set<() => void>()

function emit() {
  for (const listener of listeners) listener()
}

let applied = false

/**
 * Applies `?toolbar=1` / `?toolbar=0` to the stored value, once per load
 * rather than once per subscriber — the flag is a property of the URL, not of
 * whichever component happened to mount first.
 *
 * Returns whether there was a flag to apply, since React reads the snapshot
 * before it subscribes and needs telling if that read is already stale.
 */
function applyUrlFlag() {
  if (applied) return false
  applied = true

  const flag = new URLSearchParams(window.location.search).get("toolbar")

  if (flag === "1") window.localStorage.setItem(STORAGE_KEY, "on")
  if (flag === "0") window.localStorage.removeItem(STORAGE_KEY)

  return Boolean(flag)
}

function subscribe(onStoreChange: () => void) {
  listeners.add(onStoreChange)

  if (applyUrlFlag()) onStoreChange()

  /* Another tab changing the flag turns the toolbar on here too. */
  window.addEventListener("storage", onStoreChange)

  return () => {
    listeners.delete(onStoreChange)
    window.removeEventListener("storage", onStoreChange)
  }
}

function getSnapshot() {
  return window.localStorage.getItem(STORAGE_KEY) === "on"
}

/** Nothing is opted in on the server, so the static HTML never carries it. */
function getServerSnapshot() {
  return false
}

function getSuppressedSnapshot() {
  return new URLSearchParams(window.location.search).get("toolbar") === "0"
}

function getSuppressedServerSnapshot() {
  return false
}

/** Whether the toolbar is on, for anything that has to reflect that state. */
export function useToolbarEnabled() {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot)
}

/**
 * `?toolbar=0` hides the toggle as well as the toolbar: no toolbar, and nothing
 * offering to turn one on. `npm run shots` and `npm run thumbs` drive every
 * route with it, so a capture carries the design and not the chrome around it.
 */
export function useToolbarSuppressed() {
  return useSyncExternalStore(
    subscribe,
    getSuppressedSnapshot,
    getSuppressedServerSnapshot,
  )
}

/**
 * Turns the toolbar on or off from inside the page.
 *
 * `replaceState` rather than a navigation: the store already drives the
 * toolbar, so a reload would buy nothing but a round trip. The flag still goes
 * into the address bar, because that is what makes the URL worth copying — the
 * next reviewer gets a link that arrives already opted in.
 */
export function setToolbar(on: boolean) {
  if (on) window.localStorage.setItem(STORAGE_KEY, "on")
  else window.localStorage.removeItem(STORAGE_KEY)

  const url = new URL(window.location.href)

  if (on) url.searchParams.set("toolbar", "1")
  else url.searchParams.delete("toolbar")

  window.history.replaceState(null, "", url)

  emit()
}

/**
 * The Vercel toolbar — and with it Comments — on the deployed site.
 *
 * Preview deployments get the toolbar for free; this is for the production
 * URL, which is the one people are actually sent. It is deliberately behind a
 * flag: mounting the toolbar unconditionally prompts *every* visitor to log in
 * to Vercel, and this site answers unauthenticated requests. A reviewer turns
 * it on from the shell header; nobody else is asked for anything.
 *
 * Read through `useSyncExternalStore` rather than an effect so no route has to
 * give up static rendering, and so the flag is read the way any other external
 * store would be.
 */
export function StaffToolbar() {
  const enabled = useToolbarEnabled()

  return enabled ? <VercelToolbar /> : null
}

